begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions,pg_catalog;
select no_plan();
\ir helpers/polat_inbound_fixtures.sql
select pg_temp.polat_setup(3101);select pg_temp.polat_setup(3102);
select private.polat_configure_runtime_fixture(pg_temp.polat_id(3101,'2000'),pg_temp.polat_conv(3101));
create function pg_temp.polat_context(n integer)returns jsonb language sql as $$select public.polat_test_runtime_context_v1(pg_temp.polat_id(n,'2000'),pg_temp.polat_conv(n),(select e.id from public.domain_events e join private.polat_conversation_controls c on c.tenant_id=e.tenant_id and c.last_inbound_id::text=e.payload->>'message_id'where e.tenant_id=pg_temp.polat_id(n,'2000')and e.event_type='message.received'limit 1))$$;
select is(pg_temp.polat_context(3101)->>'profile','polat-test-runtime-v1','explicit profile is selected only after fixture setup');
select is(pg_temp.polat_context(3101)->>'financial_authority','NONE','no financial authority');
select is(pg_temp.polat_context(3101)->>'live_operations_authorized','false','no live operation');
select is(pg_temp.polat_context(3101)#>>'{input,verified_customer_language}',null,'admin locale does not select customer locale');
select is(jsonb_array_length(pg_temp.polat_context(3101)#>'{input,messages}'),1,'one source message is bounded');
select is(pg_temp.polat_context(3101)#>>'{input,messages,0,delivery}','INBOUND_OBSERVED','inbound evidence is distinct from delivery');
select is(pg_temp.polat_context(3101)#>>'{input,messages,0,content}','Hello','original source preserved');
select is(jsonb_array_length(pg_temp.polat_context(3101)->'subscription_context'),0,'no fabricated subscription');
select throws_ok($$select pg_temp.polat_context(3102)$$,'42501',null,'profile-disabled fixture denied');
select throws_ok($$select public.polat_test_runtime_context_v1(pg_temp.polat_id(3102,'2000'),pg_temp.polat_conv(3101),(select id from public.domain_events where tenant_id=pg_temp.polat_id(3101,'2000')and event_type='message.received'limit 1))$$,'42501',null,'wrong tenant and conversation uniformly denied');
select ok(not has_function_privilege('authenticated','public.polat_test_runtime_context_v1(uuid,uuid,uuid)','EXECUTE'),'browser cannot read fixture source');
select ok(not has_function_privilege('anon','public.claim_polat_test_tasks_v1(uuid,uuid,text)','EXECUTE'),'anonymous cannot claim tasks');
select ok(not has_function_privilege('service_role','private.polat_configure_runtime_fixture(uuid,uuid)','EXECUTE'),'service role cannot activate profile');
select ok(not has_table_privilege('service_role','private.polat_runtime_drafts','INSERT'),'no raw draft writer');
select ok(not has_table_privilege('authenticated','private.polat_runtime_drafts','SELECT'),'no browser private draft projection');
select ok(has_function_privilege('service_role','public.polat_test_runtime_context_v1(uuid,uuid,uuid)','EXECUTE'),'server can use guarded fixture read');
select ok((select bool_and(relrowsecurity)from pg_class where oid in('private.polat_runtime_profiles'::regclass,'private.polat_runtime_drafts'::regclass,'private.polat_runtime_steps'::regclass)),'all new private tables use RLS');
select throws_ok($$select public.claim_polat_test_tasks_v1(pg_temp.polat_id(3101,'2000'),pg_temp.polat_conv(3101),'')$$,'22023',null,'invalid worker denied');
select is(public.polat_test_runtime_recovery_v1(pg_temp.polat_id(3101,'2000'),pg_temp.polat_conv(3101)),'[]'::jsonb,'no draft is not a delivered response');
select throws_ok($$select public.polat_test_runtime_prepare_v1(pg_temp.polat_id(3101,'2000'),extensions.gen_random_uuid())$$,'42501',null,'foreign draft denied');
select is(public.polat_test_runtime_can_send_v1(pg_temp.polat_id(3101,'2000'),extensions.gen_random_uuid()),false,'missing draft cannot send');
-- Bounded source memory: >20 messages never expands a runtime context.
do $$begin for i in 2..27 loop perform pg_temp.polat_send(3101,i::text);end loop;end;$$;
select is(jsonb_array_length(pg_temp.polat_context(3101)#>'{input,messages}'),20,'history is hard bounded at 20');
select ok(length(pg_temp.polat_context(3101)::text)<20000,'source context remains small');
select ok(not(pg_temp.polat_context(3101)::text~'lease_token|invite_reference|provider_chat_id|bot_token'),'no credential, invite or worker token projection');
select is((select count(*)from public.messages where tenant_id=pg_temp.polat_id(3101,'2000')and direction='outbound'),0::bigint,'no actual outbound');
select is((select count(*)from private.verified_payment_receipts where tenant_id=pg_temp.polat_id(3101,'2000')),0::bigint,'no receipt');
select is((select count(*)from public.subscriptions where tenant_id=pg_temp.polat_id(3101,'2000')),0::bigint,'no subscription');
update public.tenants set outbound_messaging_enabled=true where id=pg_temp.polat_id(3101,'2000');
select throws_ok($$select pg_temp.polat_context(3101)$$,'42501',null,'enabling outbound invalidates the TEST profile');
select * from finish();
rollback;
